int rm_read_mdpr_streams(AVFormatContext *s, AVIOContext *pb, AVStream *st, char *mime) {
    int i, ret, num_streams, num_mdpr;

    // Read number of streams
    num_streams = avio_r8(pb);
    if (num_streams <= 0) {
        return AVERROR_INVALIDDATA;
    }

    // Read number of MDPR
    num_mdpr = avio_r8(pb);
    if (num_mdpr <= 0) {
        return AVERROR_INVALIDDATA;
    }

    // Request a sample if more than one MDPR
    if (num_mdpr > 1) {
        av_log(s, AV_LOG_DEBUG, "Requesting sample for multiple MDPR records.\n");
    }

    for (i = 0; i < num_mdpr; i++) {
        AVStream *new_st = avformat_new_stream(s, NULL);
        if (!new_st) {
            return AVERROR(ENOMEM);
        }

        // Copy codec parameters from original stream
        ret = avcodec_parameters_copy(new_st->codecpar, st->codecpar);
        if (ret < 0) {
            return ret;
        }

        // Read codec data
        if ((ret = avio_read(pb, new_st->codecpar->extradata, new_st->codecpar->extradata_size)) < 0) {
            return ret;
        }

        // Set MIME type if provided
        if (mime) {
            av_strlcpy(new_st->codecpar->mime_type, mime, sizeof(new_st->codecpar->mime_type));
        }
    }

    return 0;
}
